#include <iostream>
#include <locale>
#include <iomanip>
int main() {
    std::locale loc;  // Default locale
    std::cin.imbue(loc);
    std::string input = "$1,056.23";
    std::istringstream iss(input);
    iss.imbue(loc);
    std::ios_base::iostate err = std::ios_base::goodbit;
    std::string digits;
    const std::money_get<char>& mg = std::use_facet<std::money_get<char>>(loc);
    mg.get(iss, 0, iss, err, digits);  // Virtual dispatch occurs here for facet methods
    if (err == std::ios_base::goodbit) {
        std::cout << "Parsed digits: " << digits << std::endl;  // Outputs something like "105623"
    } else {
        std::cout << "Parsing error" << std::endl;
    }
    return 0;
}
